steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      comments(first: 50) {
        nodes {
          id
          body
          createdAt
          user {
            id
            name
            email
          }
          issue {
            id
            identifier
            title
          }
        }
      }
    }"
  }'
